const Deno = { env: { get: (k: string) => (k === "LOVABLE_API_KEY" ? process.env.GEMINI_API_KEY || undefined : process.env[k]) } };

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const LOVABLE_API_KEY = Deno.env.get('LOVABLE_API_KEY');
const LABELS = ['Normal', 'Mild', 'Moderate', 'Severe', 'Inconclusive'];

import { ENGLISH_WORDS } from './english-words.js';

type Item = { orig: string; norm: string; raw: number };
type Annotation = { word: string; type: string; suggestion: string };
// A word in the REFERENCE text that is probably wrong, rather than the learner's word.
type ReferenceIssue = {
  reference: string;      // the word as written in the reference text
  learner: string;        // what the learner wrote at that place
  suggestion: string;     // proposed replacement for the reference word ('' = none)
  reason: 'not-a-word' | 'context';
  counted: boolean;       // still counted as a learner error in the score?
  raw: number;            // position among the reference's whitespace-separated tokens
};

// ---------- Dictionary check (deterministic) ----------

let WORDS: Set<string> | null = null;
function isEnglishWord(norm: string): boolean {
  if (!WORDS) WORDS = new Set(ENGLISH_WORDS.split('\n'));
  if (/^\d+(st|nd|rd|th|s)?$/.test(norm) || /^\d[\d.,:/-]*\d$/.test(norm)) return true; // 2026, 3rd, 1990s, 10:30
  const w = norm.replace(/’/g, "'");
  if (WORDS.has(w)) return true;
  if (w.endsWith("'s") && WORDS.has(w.slice(0, -2))) return true;   // possessives
  if (w.includes('-')) return w.split('-').every((p) => p === '' || WORDS!.has(p)); // well-known
  return false;
}

// ---------- Scoring: rule-based, deterministic ----------

// Lowercase and strip punctuation at the edges of a word, so "dog." matches "dog".
function normalizeWord(w: string): string {
  return w.toLowerCase().replace(/^[^\p{L}\p{N}']+|[^\p{L}\p{N}']+$/gu, '');
}

function toItems(text: string): Item[] {
  return text.trim().split(/\s+/).filter(Boolean)
    .map((orig, raw) => ({ orig, norm: normalizeWord(orig), raw }))
    .filter((x) => x.norm.length > 0);
}

// Replaces whole reference tokens by position, keeping spacing, line breaks and edge punctuation.
function applyReferenceFixes(referenceText: string, issues: ReferenceIssue[]): string {
  const fixes = new Map(issues.filter((x) => x.suggestion).map((x) => [x.raw, x.suggestion]));
  let k = -1;
  return referenceText.split(/(\s+)/).map((part) => {
    if (!part || /^\s+$/.test(part)) return part;
    k++;
    const fix = fixes.get(k);
    if (!fix) return part;
    const m = part.match(/^([^\p{L}\p{N}']*)(.*?)([^\p{L}\p{N}']*)$/u)!;
    const core = /^\p{Lu}/u.test(m[2]) ? fix.charAt(0).toUpperCase() + fix.slice(1) : fix;
    return m[1] + core + m[3];
  }).join('');
}

// Number of single-letter edits (insert, delete, change) between two words.
function editDistance(a: string, b: string): number {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++)
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length];
}

const REVERSALS = new Set(['bd', 'db', 'pq', 'qp', 'mw', 'wm']);

// Describes how one typed word differs from the expected word.
function classifyError(expected: string, typed: string): string {
  if (typed.length === expected.length) {
    const diffs: number[] = [];
    for (let i = 0; i < expected.length; i++) if (expected[i] !== typed[i]) diffs.push(i);
    if (diffs.length === 2 && diffs[1] === diffs[0] + 1 &&
        expected[diffs[0]] === typed[diffs[1]] && expected[diffs[1]] === typed[diffs[0]]) return 'transposition';
    if (diffs.length === 1 && REVERSALS.has(expected[diffs[0]] + typed[diffs[0]])) return 'reversal';
    return 'substitution';
  }
  if (typed.length === expected.length - 1) return 'omission';
  if (typed.length === expected.length + 1) return 'insertion';
  return 'substitution';
}

// Lines up typed words with reference words in order (global sequence alignment).
// Exact matches score highest, and a misspelling ("abd" for "and") is preferred over
// unrelated words, so a repeated word such as "and" cannot pull the alignment out of
// place and one missing or extra word does not shift every word after it.
// Returns only the words that differ: pairs, missing reference words, or extra typed words.
const ALIGN = { exact: 3, similar: 1, other: -1, gap: -1 };
function isSimilar(a: string, b: string): boolean {
  return editDistance(a, b) <= Math.max(1, Math.floor(Math.max(a.length, b.length) / 2));
}
function alignWords(ref: Item[], typed: Item[]): Array<{ expected?: Item; typed?: Item }> {
  const n = ref.length, m = typed.length;
  const pairScore = (i: number, j: number) =>
    ref[i].norm === typed[j].norm ? ALIGN.exact : isSimilar(ref[i].norm, typed[j].norm) ? ALIGN.similar : ALIGN.other;
  // best[i][j] = best score for aligning ref[i..] with typed[j..]
  const best: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n; i >= 0; i--)
    for (let j = m; j >= 0; j--) {
      if (i === n && j === m) continue;
      let v = -Infinity;
      if (i < n && j < m) v = Math.max(v, pairScore(i, j) + best[i + 1][j + 1]);
      if (i < n) v = Math.max(v, ALIGN.gap + best[i + 1][j]);
      if (j < m) v = Math.max(v, ALIGN.gap + best[i][j + 1]);
      best[i][j] = v;
    }
  const out: Array<{ expected?: Item; typed?: Item }> = [];
  let i = 0, j = 0;
  while (i < n || j < m) {
    // Fixed preference order on ties (pair, then missing, then extra) keeps results repeatable.
    if (i < n && j < m && best[i][j] === pairScore(i, j) + best[i + 1][j + 1]) {
      if (ref[i].norm !== typed[j].norm) out.push({ expected: ref[i], typed: typed[j] });
      i++; j++;
    } else if (i < n && best[i][j] === ALIGN.gap + best[i + 1][j]) {
      out.push({ expected: ref[i] }); i++;
    } else {
      out.push({ typed: typed[j] }); j++;
    }
  }
  return out;
}

function scoreAgainstReference(referenceText: string, typedText: string) {
  const ref = toItems(referenceText);
  const typed = toItems(typedText);
  const annotations: Annotation[] = [];
  const referenceIssues: ReferenceIssue[] = [];
  // Real-word pairs ("form" vs "from"): the dictionary cannot say which side is wrong,
  // so they are offered to the optional sentence-context check.
  const contextCandidates: Array<{ expected: Item; typed: Item; annotation: Annotation }> = [];
  let matched = 0;
  for (const pair of alignWords(ref, typed)) {
    if (pair.expected && pair.typed) {
      if (pair.expected.norm === pair.typed.norm) { matched++; continue; }
      const refOk = isEnglishWord(pair.expected.norm);
      const typedOk = isEnglishWord(pair.typed.norm);
      if (!refOk && typedOk) {
        // The reference word is not English but the learner's word is: most likely a typo
        // in the reference, so it is not held against the learner.
        referenceIssues.push({ reference: pair.expected.orig, learner: pair.typed.orig, suggestion: pair.typed.norm,
          reason: 'not-a-word', counted: false, raw: pair.expected.raw });
        continue;
      }
      const annotation = { word: pair.typed.orig, type: classifyError(pair.expected.norm, pair.typed.norm), suggestion: pair.expected.orig };
      annotations.push(annotation);
      if (!refOk) {
        // Neither word is English: still a learner error, but the reference needs checking too.
        referenceIssues.push({ reference: pair.expected.orig, learner: pair.typed.orig, suggestion: '',
          reason: 'not-a-word', counted: true, raw: pair.expected.raw });
      } else if (typedOk) {
        contextCandidates.push({ expected: pair.expected, typed: pair.typed, annotation });
      }
    } else if (pair.expected) {
      annotations.push({ word: '(missing)', type: 'omission', suggestion: pair.expected.orig });
    } else if (pair.typed) {
      annotations.push({ word: pair.typed.orig, type: 'insertion', suggestion: '(extra word)' });
    }
  }
  // Probably two different passages when under half of the reference words were copied
  // exactly or nearly (a misspelling such as "fal" for "fall" still counts as copied).
  // alignWords lists only the unmatched words, so exact matches = reference words not listed.
  const pairs = alignWords(ref, typed);
  matched = ref.length - pairs.filter((p) => p.expected).length;
  // Reference words that are not English but were copied exactly: no learner error,
  // yet the reference still needs fixing (the learner copied the teacher's typo).
  const listed = new Set(pairs.filter((p) => p.expected).map((p) => p.expected!.raw));
  for (const item of ref) {
    if (!listed.has(item.raw) && !isEnglishWord(item.norm)) {
      referenceIssues.push({ reference: item.orig, learner: item.orig, suggestion: '', reason: 'not-a-word', counted: false, raw: item.raw });
    }
  }
  const near = pairs.filter((p) => p.expected && p.typed && isSimilar(p.expected.norm, p.typed.norm)).length;
  const referenceMismatch = ref.length >= 4 && (matched + near) / ref.length < 0.5;
  return { annotations, totalWords: ref.length, referenceIssues, contextCandidates, referenceMismatch };
}

// Optional: asks Gemini which word fits the SENTENCE CONTEXT for real-word disagreements.
// It never changes the score; a 'learner fits better' answer is shown as a suggested
// reference fix for the teacher to confirm. Both texts are sent to Google for this.
async function geminiContextCheck(referenceText: string, typedText: string,
  candidates: Array<{ expected: Item; typed: Item }>): Promise<{ fits: string[] } | { error: string }> {
  const list = candidates.slice(0, 10)
    .map((c, i) => `${i}: reference word "${c.expected.orig}" vs learner word "${c.typed.orig}"`).join('\n');
  const body = JSON.stringify({
    model: (process.env.GEMINI_MODEL || "gemini-3.8-flash"),
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      {
        role: 'system',
        content: 'You check a REFERENCE passage that a teacher typed for a reading test. A learner copied it. For each numbered pair, decide which word is correct English in the sentence where it appears: "reference" if the reference word fits the sentence, "learner" ONLY if the reference word is clearly wrong there (a typo by the teacher) and the learner word is clearly right, otherwise "unclear". Learners often write real but wrong words (dog -> bog), so prefer "reference" unless the reference word makes the sentence wrong. Reply only with JSON: {"fits": ["reference" | "learner" | "unclear", ...]} in the same order.',
      },
      { role: 'user', content: `Reference passage:\n${referenceText}\n\nLearner text:\n${typedText}\n\nPairs:\n${list}` },
    ],
  });
  try {
    const r = await fetch('https://generativelanguage.googleapis.com/v1beta/openai/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${LOVABLE_API_KEY}`, 'Content-Type': 'application/json' },
      body,
      signal: AbortSignal.timeout(15000),
    });
    if (!r.ok) return { error: `HTTP ${r.status} (${errorMessage(await r.text())})` };
    const data = await r.json();
    const parsed = JSON.parse(data.choices[0].message.content);
    const fits = Array.isArray(parsed.fits) ? parsed.fits.map((x: unknown) => String(x)) : [];
    return { fits };
  } catch (e) {
    return { error: 'could not reach Gemini: ' + (e instanceof Error ? e.message : String(e)) };
  }
}

// Used only when no reference text is given: checks a fixed list of common misspellings.
function scorePatternOnly(text: string) {
  const patterns = [
    { pattern: /\b(teh|hte)\b/gi, word: 'the', type: 'transposition' },
    { pattern: /\b(qick|quik)\b/gi, word: 'quick', type: 'transposition' },
    { pattern: /\b(borwn|bworn)\b/gi, word: 'brown', type: 'transposition' },
    { pattern: /\b(poeple|peopl)\b/gi, word: 'people', type: 'omission' },
    { pattern: /\b(thier|thir)\b/gi, word: 'their', type: 'substitution' },
    { pattern: /\b(migt|mihgt)\b/gi, word: 'might', type: 'transposition' },
  ];
  const annotations: Annotation[] = [];
  for (const p of patterns) {
    for (const match of text.match(p.pattern) || []) {
      annotations.push({ word: match, type: p.type, suggestion: p.word });
    }
  }
  return { annotations, totalWords: text.trim().split(/\s+/).filter(Boolean).length };
}

// Uncalibrated formula: error rate x 2.5, capped at 95%. Thresholds are not validated.
function toLabel(probability: number): string {
  if (probability < 0.3) return 'Normal';
  if (probability < 0.45) return 'Inconclusive';
  if (probability < 0.6) return 'Mild';
  if (probability < 0.75) return 'Moderate';
  return 'Severe';
}

// ---------- Recommendations: fixed text, or Gemini wording ----------

function staticSuggestions(label: string, annotations: Annotation[]): string[] {
  if (label === 'Normal') return ['Continue with regular reading practice', 'Explore diverse reading materials'];
  const s = [
    'Enable OpenDyslexic font for better readability',
    'Increase line spacing to 1.8 or higher',
    'Use text-to-speech for audio support',
  ];
  if (annotations.some((a) => a.type === 'transposition')) s.push('Practice letter sequence recognition exercises');
  if (annotations.some((a) => a.type === 'omission')) s.push('Use visual tracking guides while reading');
  if (annotations.some((a) => a.type === 'substitution')) s.push('Work with a reading specialist on phonics');
  if (label === 'Moderate' || label === 'Severe') s.push('Consider professional assessment for personalized support');
  return s;
}

function errorMessage(text: string): string {
  try {
    const j = JSON.parse(text);
    const e = Array.isArray(j) ? j[0]?.error : j.error;
    if (e?.message) return (e.status ? e.status + ': ' : '') + e.message;
  } catch (_) { /* not JSON */ }
  return text.slice(0, 300);
}

// Sends only the label and the error list (not the texts) and asks for wording.
// Retries briefly on busy/rate-limit errors.
async function geminiRecommendations(label: string, probability: number, annotations: Annotation[]): Promise<{ suggestions: string[] } | { error: string }> {
  const errorList = annotations.slice(0, 10)
    .map((a) => `"${a.word}" (expected "${a.suggestion}", ${a.type})`).join('; ') || 'none';
  const body = JSON.stringify({
    model: (process.env.GEMINI_MODEL || "gemini-3.8-flash"),
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      {
        role: 'system',
        content: 'You write practical reading-support recommendations for a dyslexia SCREENING tool. It is not a diagnosis. The label and score were already computed by a rule-based system: do not change, question or re-score them. Reply only with JSON in the form {"suggestions": ["...", "..."]} containing 3 to 5 short, plain-language suggestions that match the error types listed.',
      },
      {
        role: 'user',
        content: `Screening label: ${label}. Score: ${Math.round(probability * 100)}%. Errors found: ${errorList}.`,
      },
    ],
  });
  let lastError = '';
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const r = await fetch('https://generativelanguage.googleapis.com/v1beta/openai/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${LOVABLE_API_KEY}`, 'Content-Type': 'application/json' },
        body,
        signal: AbortSignal.timeout(20000),
      });
      if (r.ok) {
        const data = await r.json();
        const parsed = JSON.parse(data.choices[0].message.content);
        const list = Array.isArray(parsed.suggestions)
          ? parsed.suggestions.filter((s: unknown) => typeof s === 'string' && s.trim().length > 0).slice(0, 5)
          : [];
        if (list.length > 0) return { suggestions: list };
        return { error: 'unexpected reply format' };
      }
      lastError = `HTTP ${r.status} (${errorMessage(await r.text())})`;
      if (r.status !== 429 && r.status !== 503) break;
    } catch (e) {
      lastError = 'could not reach Gemini: ' + (e instanceof Error ? e.message : String(e));
    }
    if (attempt < 3) await new Promise((res) => setTimeout(res, 1500 * attempt));
  }
  return { error: lastError };
}

// ---------- HTTP handler ----------

export default (async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { user_id, text, reference_text } = await req.json();
    console.log('Received prediction request:', { user_id, textLength: text?.length, hasReference: !!reference_text });

    if (!text || typeof text !== 'string' || text.trim().length < 10) {
      return new Response(
        JSON.stringify({ error: 'Invalid input. User text must be at least 10 characters.' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const usedReference = !!(reference_text && typeof reference_text === 'string' && reference_text.trim().length > 0);
    const scored = usedReference
      ? scoreAgainstReference(reference_text, text)
      : scorePatternOnly(text);

    const { annotations, totalWords } = scored;
    const referenceIssues: ReferenceIssue[] = 'referenceIssues' in scored ? scored.referenceIssues : [];
    const referenceMismatch = 'referenceMismatch' in scored ? scored.referenceMismatch : false;

    // Sentence-context check for real-word disagreements (needs Gemini; never changes the score).
    let contextCheck: 'gemini' | 'skipped' | 'failed' = 'skipped';
    let contextCheckError = '';
    if (usedReference && LOVABLE_API_KEY && !referenceMismatch && 'contextCandidates' in scored && scored.contextCandidates.length > 0) {
      const c = await geminiContextCheck(reference_text, text, scored.contextCandidates);
      if ('fits' in c) {
        contextCheck = 'gemini';
        scored.contextCandidates.slice(0, 10).forEach((cand, i) => {
          if (c.fits[i] === 'learner') {
            referenceIssues.push({ reference: cand.expected.orig, learner: cand.typed.orig, suggestion: cand.typed.norm,
              reason: 'context', counted: true, raw: cand.expected.raw });
          }
        });
      } else {
        contextCheck = 'failed';
        contextCheckError = c.error;
      }
    }
    referenceIssues.sort((a, b) => a.raw - b.raw);
    const correctedReference = usedReference && referenceIssues.some((x) => x.suggestion)
      ? applyReferenceFixes(reference_text, referenceIssues) : undefined;

    const errorRate = totalWords > 0 ? annotations.length / totalWords : 0;
    let probability = Math.min(0.95, errorRate * 2.5);
    if (totalWords < 10) probability = Math.max(0.4, probability * 0.7); // short texts: lower confidence
    const label = toLabel(probability);

    let suggestions = staticSuggestions(label, annotations);
    let recommendationsSource = 'built-in';
    let fallbackReason = '';

    if (usedReference && LOVABLE_API_KEY) {
      const g = await geminiRecommendations(label, probability, annotations);
      if ('suggestions' in g) {
        suggestions = g.suggestions;
        recommendationsSource = 'gemini';
      } else {
        fallbackReason = g.error;
        console.error('Gemini recommendations failed:', g.error);
      }
    }

    const result = {
      probability,
      label,
      annotations: annotations.slice(0, 20),
      suggestions,
      engine: usedReference ? 'rule-based' : 'pattern-match',
      recommendationsSource,
      ...(fallbackReason ? { fallbackReason } : {}),
      referenceIssues: referenceIssues.map(({ raw: _raw, ...rest }) => rest),
      ...(correctedReference ? { correctedReference } : {}),
      referenceMismatch,
      contextCheck,
      ...(contextCheckError ? { contextCheckError } : {}),
    };

    console.log('Prediction result:', { label, probability, annotationCount: annotations.length, recommendationsSource });

    return new Response(JSON.stringify(result), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  } catch (error) {
    console.error('Error in predict function:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error', message: error instanceof Error ? error.message : 'Unknown error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});
